+    fn flush_pending_ccx(&mut self) -> std::io::Result<()> {
+        let pending = std::mem::take(&mut self.pending_ccx);
+        for op in pending {
+            self.write_raw_op(&op)?;
+        }
+        Ok(())
+    }
+
+    fn write_op(&mut self, op: &Op) -> std::io::Result<()> {
+        if self.cancel_adjacent_ccx && op.kind == OperationType::CCX {
+            if self.pending_ccx.last() == Some(op) {
+                self.pending_ccx.pop();
+                self.removed_ccx += 2;
+            } else {
+                self.pending_ccx.push(*op);
+            }
+            return Ok(());
+        }
+        self.flush_pending_ccx()?;
+        self.write_raw_op(op)
+    }
